"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["91652"],{89534(e,t,n){n.r(t),n.d(t,{metadata:()=>i,default:()=>h,frontMatter:()=>c,contentTitle:()=>d,toc:()=>u,assets:()=>p});var i=JSON.parse('{"id":"nhcx/v1/api/communication/endpoints/communication-v1-communication-request","title":"Payer: send a communication request","description":"Payer pushes a Task plus Communication bundle to a provider mid-claim: TAT alerts, wallet or policy changes, grievances or extra-information requests.","source":"@site/docs/nhcx/v1/api/communication/endpoints/communication-v1-communication-request.mdx","sourceDirName":"nhcx/v1/api/communication/endpoints","slug":"/nhcx/v1/api/communication/endpoints/communication-v1-communication-request","permalink":"/docs/pr-44/docs/nhcx/v1/api/communication/endpoints/communication-v1-communication-request","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Payer: send a communication request","sidebar_label":"Payer: send a communication request","sidebar_class_name":"api-method api-method--post","description":"Payer pushes a Task plus Communication bundle to a provider mid-claim: TAT alerts, wallet or policy changes, grievances or extra-information requests.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-communication.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Overview","permalink":"/docs/pr-44/docs/nhcx/v1/api/communication/"},"next":{"title":"Provider: acknowledge the communication","permalink":"/docs/pr-44/docs/nhcx/v1/api/communication/endpoints/communication-v1-communication-on-request"}}'),a=n(62540),r=n(43023),o=n(85030),s=JSON.parse('{"id":"communication_v1_communication_request","module":"Communication","moduleId":"communication","kind":"operation","method":"POST","path":"/v1/communication/request","server":"https://apisbx.abdm.gov.in/hcx","servers":[{"url":"https://apisbx.abdm.gov.in/hcx","description":"Sandbox, NHCX exchange."},{"url":"https://apisprod.nha.gov.in/hcx","description":"Production."}],"summary":"Payer: send a communication request","title":"Payer: send a communication request","description":"Payer pushes a Task plus Communication bundle to a provider mid-claim: TAT alerts, wallet or policy changes, grievances or extra-information requests.\\n\\n### Business purpose\\n\\nEvery other NHCX exchange is provider-initiated and expects a matching response. Communication inverts that: it is the payer\'s asynchronous, event-driven channel into the hospital system, used when something must be said about an in-flight case without the provider having asked. It carries TAT breach alerts, grievance notices, wallet or benefit updates, policy or package-rate changes, requests for additional evidence and claim-arbitration intimations. Hospitals benefit because these signals arrive in a structured, routable bundle rather than by phone or email, and payers benefit because adjudication can proceed without waiting for an out-of-band exchange.\\n\\n### When to use\\n\\nThe payer uses it to send the provider a message outside the pre-authorisation or claim flow, such as a delay notice, a grievance or a request for more information. The workflow code in the header must match the related claim or pre-authorisation.\\n\\n### Preconditions\\n\\n- A valid access token and the provider\'s certificate.\\n- The bundle is encrypted for the provider.\\n- The header carries `x-hcx-status` `request.initiated` and a fresh correlation ID.\\n\\n### Postconditions\\n\\n- NHCX answers `202` at once. That only means the message was accepted.\\n- The provider\'s acknowledgement arrives later on `/v1/communication/on_request`, with the same correlation ID.\\n\\n### Common mistakes\\n\\n- Treating the `202` as the provider\'s answer.\\n- Sending a workflow code that does not match the related claim or pre-authorisation.\\n- Reusing a correlation ID from an earlier or failed cycle.\\n- Using it in place of the query inside a `ClaimResponse`.\\n\\n### Best practices\\n\\n- Mint a new UUID for x-hcx-API_call_ID on every call and for x-hcx-correlation_ID on every new communication cycle, including retries after failure.\\n- Put the routing intent in Task.reasonCode and the message classification in Communication.category, topic and priority; pair additionalinfo with category instruction or questionnaire.\\n- Use IST timestamps; UTC causes validation failures.\\n- Persist the correlation ID before posting so the on_request acknowledgement can be matched.\\n- Expect up to five redeliveries if the provider mis-acknowledges; keep your own handling idempotent.\\n- Implement v1/error so a message that never reaches the provider is reported back to you.\\n\\n### Related scenario\\n\\nA state health agency\'s TPA notices that a cashless claim from a district hospital has sat in adjudication past the scheme\'s turnaround threshold. It builds a Task bundle with reasonCode tatquery, category reminder, topic progress-update and priority asap, encrypts it for the hospital and posts /v1/communication/request with the workflow ID of the claim submitted earlier on /v1/claim/submit. The gateway returns 202 and forwards the bundle. The hospital\'s claims desk is alerted, and its system posts the acknowledgement Task on /v1/communication/on_request with the same correlation ID. Adjudication then continues and the outcome arrives on /v1/claim/on_submit as usual.\\n\\n### Specification\\n\\nChapter [Communication](/docs/nhcx/v1/reference/fhir/communication) of the NHCX integration specification.","gateway":"nhcx","security":[{"name":"bearerAuth","type":"apiKey","in":"header","headerName":"bearer_auth","description":"Every NHCX call carries the access token from the session call in a header named `bearer_auth`, as the word `Bearer`, a space and the token. NHCX reads `bearer_auth`, not `Authorization`.","example":"Bearer <access token>","prefix":"Bearer "}],"headers":[],"pathParams":[],"queryParams":[],"body":[{"name":"payload","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"payload":"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOi4uLn0.encrypted_key.iv.ciphertext.tag"},"protectedHeader":[{"name":"alg","type":"string","required":true,"description":"Key management algorithm. Always `RSA-OAEP-256`: the content key is wrapped with the recipient\'s RSA public key.","example":"RSA-OAEP-256"},{"name":"enc","type":"string","required":true,"description":"Content encryption algorithm. Always `A256GCM`.","example":"A256GCM"},{"name":"x-hcx-sender_code","type":"string","required":true,"description":"Your participant code. Mandatory on the envelope.","example":"<payer participant code>"},{"name":"x-hcx-recipient_code","type":"string","required":true,"description":"The recipient\'s. For a provider, the processor code from the policy lookup. Mandatory on the envelope.","example":"<provider participant code>"},{"name":"x-hcx-api_call_id","type":"string","required":true,"description":"Fresh on every message, including responses. Mandatory on the envelope.","example":"<uuid>"},{"name":"x-hcx-request_id","type":"string","required":false,"description":"One per originating request. The Open Protocol page marks it Mandatory; the Technical Specifications page marks it Optional. Optional on the envelope. Send it anyway, as a fresh UUID per originating request: it is cheap and satisfies both readings until NHA rules.","example":"<uuid>"},{"name":"x-hcx-correlation_id","type":"string","required":true,"description":"The thread that ties a request to its answers. [The correlation ID rule](/docs/nhcx/v1/reference/envelope-fields#the-correlation-id-rule-in-full) says when to reuse it. Mandatory on the envelope.","example":"<uuid>"},{"name":"x-hcx-workflow_id","type":"string","required":false,"description":"Which step, or which case. [The workflow code](/docs/nhcx/v1/reference/envelope-fields#the-workflow-code-means-two-different-things) explains both readings. Optional on the envelope.","example":"15"},{"name":"x-hcx-timestamp","type":"string","required":true,"description":"The time the message was made. [Timestamp](/docs/nhcx/v1/reference/envelope-fields#timestamp) gives the format. Mandatory on the envelope.","example":"<iso timestamp>"},{"name":"x-hcx-status","type":"string","required":true,"description":"Where this message stands. [Status words](/docs/nhcx/v1/reference/envelope-fields#status-words) lists the values. Mandatory on the envelope.","example":"request.initiated"},{"name":"x-hcx-ben-abha-id","type":"string","required":false,"description":"The beneficiary\'s ABHA number. Optional: send it when the beneficiary has an ABHA number. Optional on the envelope.","example":"<14-digit ABHA number>"}],"responses":[{"status":"202","description":"The gateway validates the JWE headers, workflow id and NIIP and returns HTTP 202 with a StatusSuccessResponse (timestamp, api_call_id, correlation_id, result with sender_code, recipient_code, entity_type and protocol_status, and an error object).","example":{"timestamp":"25/08/2026 11:46:35:120","api_call_id":"a1b2c3d4-e5f6-7890-abcd-ef1234567890","correlation_id":"11223344-5566-7788-99aa-bbccddeeff00","result":{"sender_code":"<payer participant code>","recipient_code":"<provider participant code>","entity_type":"task","protocol_status":"request.queued"},"error":{"code":"","message":""}},"synthesised":false,"fields":[{"name":"timestamp","type":"string","required":false,"description":""},{"name":"api_call_id","type":"string","required":false,"description":""},{"name":"correlation_id","type":"string","required":false,"description":""},{"name":"result","type":"object","required":false,"description":""},{"name":"result.sender_code","type":"string","required":false,"description":""},{"name":"result.recipient_code","type":"string","required":false,"description":""},{"name":"result.entity_type","type":"string","required":false,"description":""},{"name":"result.protocol_status","type":"string","required":false,"description":""},{"name":"error","type":"object","required":false,"description":""},{"name":"error.code","type":"string","required":false,"description":""},{"name":"error.message","type":"string","required":false,"description":""}]}],"curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/v1/communication/request \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOi4uLn0.encrypted_key.iv.ciphertext.tag\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/v1/communication/request \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOi4uLn0.encrypted_key.iv.ciphertext.tag\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/hcx/v1/communication/request\\",\\n    headers={\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOi4uLn0.encrypted_key.iv.ciphertext.tag\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node.js","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/hcx/v1/communication/request\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOi4uLn0.encrypted_key.iv.ciphertext.tag\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"},{"id":"java","label":"Java","language":"java","code":"import java.net.URI;\\nimport java.net.http.HttpClient;\\nimport java.net.http.HttpRequest;\\nimport java.net.http.HttpResponse;\\n\\nHttpClient client = HttpClient.newHttpClient();\\nHttpRequest request = HttpRequest.newBuilder()\\n    .uri(URI.create(\\"https://apisbx.abdm.gov.in/hcx/v1/communication/request\\"))\\n    .header(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n    .header(\\"Content-Type\\", \\"application/json\\")\\n    .method(\\"POST\\", HttpRequest.BodyPublishers.ofString(\\"\\"\\"\\n        {\\n            \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOi4uLn0.encrypted_key.iv.ciphertext.tag\\"\\n        }\\n        \\"\\"\\"))\\n    .build();\\n\\nHttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());\\nSystem.out.println(response.statusCode() + \\" \\" + response.body());"},{"id":"php","label":"PHP","language":"php","code":"<?php\\n\\n$ch = curl_init(\'https://apisbx.abdm.gov.in/hcx/v1/communication/request\');\\ncurl_setopt_array($ch, [\\n    CURLOPT_CUSTOMREQUEST => \'POST\',\\n    CURLOPT_RETURNTRANSFER => true,\\n    CURLOPT_HTTPHEADER => [\\n        \'bearer_auth: Bearer <access token>\',\\n        \'Content-Type: application/json\',\\n    ],\\n    CURLOPT_POSTFIELDS => <<<\'JSON\'\\n    {\\n        \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOi4uLn0.encrypted_key.iv.ciphertext.tag\\"\\n    }\\n    JSON,\\n]);\\n\\n$response = curl_exec($ch);\\necho curl_getinfo($ch, CURLINFO_HTTP_CODE), \' \', $response, PHP_EOL;"},{"id":"go","label":"Go","language":"go","code":"package main\\n\\nimport (\\n\\t\\"fmt\\"\\n\\t\\"io\\"\\n\\t\\"net/http\\"\\n\\t\\"strings\\"\\n)\\n\\nfunc main() {\\n\\tbody := strings.NewReader(`{\\n  \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOi4uLn0.encrypted_key.iv.ciphertext.tag\\"\\n}`)\\n\\treq, err := http.NewRequest(\\"POST\\", \\"https://apisbx.abdm.gov.in/hcx/v1/communication/request\\", body)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\treq.Header.Set(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n\\treq.Header.Set(\\"Content-Type\\", \\"application/json\\")\\n\\n\\tresp, err := http.DefaultClient.Do(req)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\tdefer resp.Body.Close()\\n\\tout, _ := io.ReadAll(resp.Body)\\n\\tfmt.Println(resp.StatusCode, string(out))\\n}"},{"id":"csharp","label":"C#","language":"csharp","code":"using var client = new HttpClient();\\nvar request = new HttpRequestMessage(new HttpMethod(\\"POST\\"), \\"https://apisbx.abdm.gov.in/hcx/v1/communication/request\\");\\nrequest.Headers.TryAddWithoutValidation(\\"bearer_auth\\", \\"Bearer <access token>\\");\\nrequest.Content = new StringContent(\\"\\"\\"\\n    {\\n        \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOi4uLn0.encrypted_key.iv.ciphertext.tag\\"\\n    }\\n    \\"\\"\\", System.Text.Encoding.UTF8, \\"application/json\\");\\n\\nvar response = await client.SendAsync(request);\\nConsole.WriteLine($\\"{(int)response.StatusCode} {await response.Content.ReadAsStringAsync()}\\");"},{"id":"ruby","label":"Ruby","language":"ruby","code":"require \'net/http\'\\n\\nuri = URI(\'https://apisbx.abdm.gov.in/hcx/v1/communication/request\')\\nrequest = Net::HTTP::Post.new(uri)\\nrequest[\'bearer_auth\'] = \'Bearer <access token>\'\\nrequest[\'Content-Type\'] = \'application/json\'\\nrequest.body = <<~\'JSON\'\\n  {\\n    \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOi4uLn0.encrypted_key.iv.ciphertext.tag\\"\\n  }\\nJSON\\n\\nresponse = Net::HTTP.start(uri.hostname, uri.port, use_ssl: uri.scheme == \'https\') do |http|\\n  http.request(request)\\nend\\nputs response.code, response.body"}]}');let c={title:"Payer: send a communication request",sidebar_label:"Payer: send a communication request",sidebar_class_name:"api-method api-method--post",description:"Payer pushes a Task plus Communication bundle to a provider mid-claim: TAT alerts, wallet or policy changes, grievances or extra-information requests.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-communication.yaml",generated:!0},d,p={},u=[{value:"Callbacks",id:"callbacks",level:2}];function l(e){let t={a:"a",code:"code",h2:"h2",li:"li",ul:"ul",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(o.A,{operation:s}),"\n",(0,a.jsx)(t.h2,{id:"callbacks",children:"Callbacks"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:["NHCX delivers this call to the provider, on the provider's own ",(0,a.jsx)(t.code,{children:"/v1/communication/request"}),", not back to you. ",(0,a.jsx)(t.a,{href:"/docs/nhcx/v1/api/communication/endpoints/communication-webhook-v1-communication-request",children:"Provider receives a communication request"}),"."]}),"\n",(0,a.jsxs)(t.li,{children:["The provider's answer comes back to you on ",(0,a.jsx)(t.a,{href:"/docs/nhcx/v1/api/communication/endpoints/communication-webhook-v1-communication-on-request",children:(0,a.jsx)(t.code,{children:"/v1/communication/on_request"})}),", the callback you host."]}),"\n"]})]})}function h(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}}}]);